import os
root = Path.cwd()
for proc in Path('/proc').glob('[0-9]*'):
    try:
        if (proc / 'cwd').resolve() == root:
            print(proc.name, (proc / 'comm').read_text().strip())
    except (OSError, PermissionError):
        pass
PY"

